      arr.push("黄林晶带你走到营地后面，那里有一个巨大的法阵——七道印的原型。");
      arr.push("「这是七印的设计图。」他指着法阵。「每一道印对应一种情感。但印的作用不是「封印」——是「转化」。」");
      arr.push("你愣住了。");
      arr.push("「我把七种情感从人类身上切除，但它们不会消失——能量守恒。我把它们转化成了「原初之物」——七种有自我意识的情感实体。然后用七印把它们分别困住，让它们慢慢「消散」。」");
      arr.push("「但我算错了。」黄林晶的手在抖。「它们没有消散。它们在成长。被封印的情感，反而变得更纯粹、更强大。三千年后，它们会比封印它们的时候强十倍。」");
      arr.push("「所以第一印碎了。不是因为兽人——是因为饥饿已经强到印关不住了。其他六道印，也快了。」");
      arr.push("「我留了后门，是因为我知道——我的方法只是延缓。真正的解决方案，需要有人找到一种方式，让七种情感重新回到世界，但不会导致「情感之灾」。」");
      arr.push("他看着你，眼睛里有三千年后的疲惫——不，是三千年后的预见。「你能做到吗？」");
      arr.push("你不知道怎么回答。");
      arr.push("黄林晶从怀里拿出一个东西——一个小小的、发光的种子。「这是「完整之种」。我用了五十年提炼出来的——七种情感的平衡体。如果你能在第七印，用这个种子……也许能让世界重新完整，但不会灾难。」");
      arr.push("「但我不确定。这只是一个理论。你愿意试吗？」");
